import{_ as e,c as a,o,ag as n}from"./chunks/framework.Ci10AEOF.js";const g=JSON.parse('{"title":"Polling Settings","description":"Interval, time, and cron schedule configuration","frontmatter":{"title":"Polling Settings","description":"Interval, time, and cron schedule configuration"},"headers":[],"relativePath":"engine/polling_settings.md","filePath":"engine/polling_settings.md","lastUpdated":1793057853000}'),r={name:"engine/polling_settings.md"};function d(s,t,i,l,h,c){return o(),a("div",null,t[0]||(t[0]=[n('<h1 id="polling-settings" tabindex="-1">Polling Settings <a class="header-anchor" href="#polling-settings" aria-label="Permalink to &quot;Polling Settings&quot;">​</a></h1><p>Source connectors that poll for data (Database Reader, File Reader, JavaScript Reader) support configurable polling schedules.</p><h2 id="polling-schedule-types" tabindex="-1">Polling schedule types <a class="header-anchor" href="#polling-schedule-types" aria-label="Permalink to &quot;Polling schedule types&quot;">​</a></h2><h3 id="interval" tabindex="-1">Interval <a class="header-anchor" href="#interval" aria-label="Permalink to &quot;Interval&quot;">​</a></h3><p>Polls at a fixed interval. The schedule is built when the source connector starts, and poll times are aligned to the start of the day&#39;s Active Time range, or to midnight when Active Time is All Day or the range crosses midnight. The first poll runs at the next multiple of the interval measured from that point, not one interval after the connector starts. A 6-hour interval polls at 00:00, 06:00, 12:00, and 18:00 no matter when the channel came up.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Interval</strong></td><td>Time between polls. Enter a number and select the unit: milliseconds, seconds, minutes, or hours. The value must be greater than zero and less than 24 hours. It is stored in the channel as <code>pollingFrequency</code>, in milliseconds.</td></tr></tbody></table><p>Example: Poll every 5 seconds.</p><p>The schedule exists only while the source connector is running. Deploying a channel starts the connector unless the channel&#39;s initial state is Stopped or Paused, and a channel deployed in either of those states does not poll until it is started. Enable Poll Once on Start to get a poll the moment the connector starts, ahead of the aligned schedule.</p><h3 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h3><p>Polls once per day at a specific time.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Time</strong></td><td>The time of day to poll (hour and minute)</td></tr></tbody></table><p>Example: Poll once daily at 6:00 AM.</p><h3 id="cron" tabindex="-1">Cron <a class="header-anchor" href="#cron" aria-label="Permalink to &quot;Cron&quot;">​</a></h3><p>Polls according to one or more cron expressions.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Cron Jobs</strong></td><td>A table of cron expressions, each with an optional description</td></tr></tbody></table><h4 id="cron-expression-format" tabindex="-1">Cron expression format <a class="header-anchor" href="#cron-expression-format" aria-label="Permalink to &quot;Cron expression format&quot;">​</a></h4><p>The engine hands each expression to Quartz, which needs six fields plus an optional seventh field for the year:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>second minute hour day-of-month month day-of-week [year]</span></span></code></pre></div><p>Quartz cannot combine a day-of-month value with a day-of-week value, so one of the two fields must be <code>?</code>. An expression that sets both is rejected as invalid.</p><table tabindex="0"><thead><tr><th>Field</th><th>Values</th><th>Special Characters</th></tr></thead><tbody><tr><td>Second</td><td>0-59</td><td><code>, - * /</code></td></tr><tr><td>Minute</td><td>0-59</td><td><code>, - * /</code></td></tr><tr><td>Hour</td><td>0-23</td><td><code>, - * /</code></td></tr><tr><td>Day of Month</td><td>1-31</td><td><code>, - * ? / L W</code></td></tr><tr><td>Month</td><td>1-12 or JAN-DEC</td><td><code>, - * /</code></td></tr><tr><td>Day of Week</td><td>1-7 or SUN-SAT</td><td><code>, - * ? / L #</code></td></tr><tr><td>Year (optional)</td><td>Up to 100 years after the current year. A schedule that can never fire, such as a later or a past year, stops the channel from starting</td><td><code>, - * /</code></td></tr></tbody></table><h4 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Expression</th><th>Schedule</th></tr></thead><tbody><tr><td><code>0 0/5 * * * ?</code></td><td>Every 5 minutes</td></tr><tr><td><code>0 0 8 * * ?</code></td><td>Daily at 8:00 AM</td></tr><tr><td><code>0 0 8,17 * * ?</code></td><td>Daily at 8:00 AM and 5:00 PM</td></tr><tr><td><code>0 0 */2 * * ?</code></td><td>Every 2 hours</td></tr><tr><td><code>0 0 9-17 ? * MON-FRI</code></td><td>Hourly from 9 AM to 5 PM, weekdays only</td></tr><tr><td><code>0 30 6 ? * MON</code></td><td>Every Monday at 6:30 AM</td></tr><tr><td><code>0 0 0 1 * ?</code></td><td>First day of every month at midnight</td></tr></tbody></table><h2 id="common-settings" tabindex="-1">Common settings <a class="header-anchor" href="#common-settings" aria-label="Permalink to &quot;Common settings&quot;">​</a></h2><p>These settings are available regardless of which schedule type is selected:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Schedule Type</strong></td><td>Interval, Time, or Cron</td></tr><tr><td><strong>Poll Once on Start</strong></td><td>Poll once as soon as the source connector starts, before the scheduled poll</td></tr></tbody></table><h3 id="poll-once-on-start" tabindex="-1">Poll Once on Start <a class="header-anchor" href="#poll-once-on-start" aria-label="Permalink to &quot;Poll Once on Start&quot;">​</a></h3><p>When enabled, the connector polls once as soon as the source connector starts, without waiting for the first scheduled poll time. The source connector starts when the channel starts, when a paused channel resumes, and when a deploy leaves the channel started.</p><h2 id="advanced-polling-settings" tabindex="-1">Advanced polling settings <a class="header-anchor" href="#advanced-polling-settings" aria-label="Permalink to &quot;Advanced polling settings&quot;">​</a></h2><p>The Advanced Settings dialog (wrench icon) is available for Interval and Time schedule types, but not for Cron.</p><h3 id="active-days" tabindex="-1">Active Days <a class="header-anchor" href="#active-days" aria-label="Permalink to &quot;Active Days&quot;">​</a></h3><p>Sets the days polling runs on.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Weekly</strong></td><td>Select specific days of the week (Sunday through Saturday) when polling is active. At least one day must be selected.</td></tr><tr><td><strong>Monthly</strong></td><td>Select a specific day of the month (1-31) when polling is active.</td></tr></tbody></table><h3 id="active-time-interval-only" tabindex="-1">Active Time (Interval only) <a class="header-anchor" href="#active-time-interval-only" aria-label="Permalink to &quot;Active Time (Interval only)&quot;">​</a></h3><p>Controls the time window during which interval-based polling is active. This setting is not available for Time schedule type (since Time already specifies a single poll time).</p><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>All Day</strong></td><td>Polling may occur at any time during the day (default).</td></tr><tr><td><strong>Range</strong></td><td>Polling only occurs during the specified time range (e.g., 8:00 AM to 5:00 PM).</td></tr></tbody></table><h2 id="polling-vs-listener-connectors" tabindex="-1">Polling vs. listener connectors <a class="header-anchor" href="#polling-vs-listener-connectors" aria-label="Permalink to &quot;Polling vs. listener connectors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Behavior</th><th>Polling (Reader)</th><th>Listener</th></tr></thead><tbody><tr><td><strong>Initiation</strong></td><td>OIE pulls data on a schedule</td><td>The sender pushes data</td></tr><tr><td><strong>Connectors</strong></td><td>Database Reader, File Reader, JavaScript Reader</td><td>TCP Listener, HTTP Listener, Channel Reader, JMS Listener, Web Service Listener, DICOM Listener</td></tr><tr><td><strong>Schedule</strong></td><td>Interval, time, or cron</td><td>N/A (always listening)</td></tr><tr><td><strong>Latency</strong></td><td>Depends on the schedule</td><td>Processed as it arrives</td></tr></tbody></table>',37)]))}const u=e(r,[["render",d]]);export{g as __pageData,u as default};
